print "candidate count ".scalar(@cand)." unique ".scalar(keys %cand)."'"\\n\";
for my "'$item (["sgps","$base/data/inputs/sgps_peptide_report/SGPS_peptide-report.tabular"],["maxquant","$base/data/inputs/maxquant_peptide_report/MaxQuant-peptide-report.tabular"]){
  my ($name,$path)=@$item; open my $fh,"<",$path or die $!; my $hdr=<$fh>; chomp $hdr; $hdr =~ s/'"\\r"'$//; my @h=split /'"\\t/,"'$hdr,-1; my %idx; @idx{@h}=0..$#h; print "$name ncols ".scalar(@h)." firstcols ".join("|",@h[0..($#h<9?$#h:9)])."'"\\n\"; my "'$seqi=$idx{Sequence}; my $proti=exists $idx{"Protein(s)"}?$idx{"Protein(s)"}:$idx{Proteins}; my ($rows,%peps,@examples)=(0); while(<$fh>){chomp; s/'"\\r"'$//; my @f=split /'"\\t/,"'$_,-1; my $seq=uc($f[$seqi]//""); next unless $cand{$seq}; $rows++; $peps{$seq}=1; push @examples, "$seq'"\\t\".("'$f[$proti]//"") if @examples<10; } print "$name matched rows $rows unique peptides ".scalar(keys %peps)."'"\\n\"; print join(\"\\n\",@examples),\"\\n\"; }
'"

